 {
     public DbSet<Product> Products => Set<Product>();
     protected override void OnModelCreating(ModelBuilder modelBuilder)
     {
         modelBuilder.Entity<Product>(entity =>
         {
             entity.ToContainer("Products");

             // EF Core 9 changed the default discriminator property from "Discriminator" to "$type".
             // Existing 500K documents use "Discriminator" — keep the old name for data compatibility
             // and to preserve direct SQL queries that reference c.Discriminator.
             entity.HasDiscriminator<string>("Discriminator");

             // EF Core 9 changed id format from "Product|123" to just "123".
             // Existing documents use the compound format — keep it so FindAsync/point-reads work.
             entity.HasRootDiscriminatorInJsonId(true);
         });

         // Removed: HasIndex() now throws on Cosmos DB entities in EF Core 9.
         // Manage indexing through the container's indexing policy (Azure Portal / Bicep / Terraform).
     }
 }
 class Product { public int Id { get; set; } public string Sku { get; set; } }

